WITH valid_orders AS (SELECT order_id, member_id, store_id, ordered_at, paid_cents - refund_cents AS net_cents FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0), ranked AS (SELECT vo.order_id, vo.member_id, vo.store_id, vo.ordered_at, vo.net_cents, ROW_NUMBER() OVER (PARTITION BY vo.member_id ORDER BY vo.ordered_at, vo.order_id) AS rn FROM valid_orders vo) SELECT order_id, member_id, store_id, ordered_at, net_cents, rn = 1 AS is_first_order FROM ranked